// Oware (Abapa) for two players. Twelve pits in a ring, indices 0-11:
// seat 0 owns pits 0-5, seat 1 owns pits 6-11, four seeds per pit (48 total).
// Captured seeds go to a store off the board (state.stores). Sowing is
// counterclockwise: increasing pit index, wrapping from 11 to 0, starting at
// the pit after the chosen one; a sowing that laps the board skips the
// starting pit. A capture takes an opponent pit the last seed makes exactly
// 2 or 3, and keeps going backwards while the same holds -- unless that
// would capture every seed the opponent has left (grand slam), in which
// case nothing is captured. If the opponent side is empty at the start of a
// turn, only moves that sow into it are legal; a player who cannot feed an
// empty opponent side ends the game. The game also ends as soon as a store
// passes 24, or when at most 6 seeds remain on the board. In every ending
// except the over-24 one the stores alone decide, and seeds still on the
// board are awarded to nobody.
function owCopy(s) { return JSON.parse(JSON.stringify(s)); }
function owIsOpp(pit, seat) { return seat === 0 ? pit >= 6 : pit < 6; }
function owSideEmpty(s, seat) {
  var lo = seat === 0 ? 0 : 6;
  for (var i = lo; i < lo + 6; i++) if (s.pits[i] > 0) return false;
  return true;
}
function owBoardTotal(s) { var t = 0; for (var i = 0; i < 12; i++) t += s.pits[i]; return t; }
// Simulate sowing from pit on a scratch copy; how many seeds land on the
// opponent side? Used by the feeding rule and the computer player.
function owSownIntoOpp(pits, seat, pit) {
  var b = pits.slice(), seeds = b[pit], pos = pit, left = seeds, fed = 0;
  b[pit] = 0;
  while (left > 0) {
    pos = (pos + 1) % 12;
    if (pos === pit) continue;
    b[pos]++; left--;
    if (owIsOpp(pos, seat)) fed++;
  }
  return fed;
}
// Sow and capture on a state-like {pits, stores}; returns seeds captured.
// When rec is supplied it is filled with the ordered landing pit of every
// seed sown (landings, in sowing order) and, when a capture actually
// happens, the captured pits in capture order (chain order: the last pit
// first, then backwards) with the seed count taken from each.
function owSow(s, seat, pit, rec) {
  var seeds = s.pits[pit], pos = pit, left = seeds, last = pit;
  s.pits[pit] = 0;
  if (rec) { rec.landings = []; rec.captures = []; rec.captured = 0; }
  while (left > 0) {
    pos = (pos + 1) % 12;
    if (pos === pit) continue;  // a lapping sowing skips the starting pit
    s.pits[pos]++; left--; last = pos;
    if (rec) rec.landings.push(pos);
  }
  var captured = 0;
  if (owIsOpp(last, seat) && (s.pits[last] === 2 || s.pits[last] === 3)) {
    var chain = [], p = last;
    while (owIsOpp(p, seat) && (s.pits[p] === 2 || s.pits[p] === 3)) {
      chain.push(p); p = (p + 11) % 12;
    }
    var oppLeft = 0;
    for (var i = 0; i < 12; i++) if (owIsOpp(i, seat) && chain.indexOf(i) < 0) oppLeft += s.pits[i];
    if (oppLeft > 0) {  // grand-slam rule: capturing everything captures nothing
      for (var j = 0; j < chain.length; j++) {
        if (rec) rec.captures.push({pit: chain[j], seeds: s.pits[chain[j]]});
        captured += s.pits[chain[j]]; s.stores[seat] += s.pits[chain[j]]; s.pits[chain[j]] = 0;
      }
      if (rec) rec.captured = captured;
    }
  }
  return captured;
}
function owLegalFor(s, seat) {
  if (s.over) return [];
  var oppEmpty = owSideEmpty(s, 1 - seat), out = [], lo = seat === 0 ? 0 : 6;
  for (var pit = lo; pit < lo + 6; pit++) {
    if (s.pits[pit] <= 0) continue;
    if (oppEmpty && owSownIntoOpp(s.pits, seat, pit) === 0) continue;  // feeding rule
    out.push({type: 'sow', pit: pit});
  }
  return out;
}
function owLegal(s) { return owLegalFor(s, s.turn); }
function owFinish(s) {
  s.over = true;
  s.winner = s.stores[0] === s.stores[1] ? -1 : (s.stores[0] > s.stores[1] ? 0 : 1);
}
function owPayouts(s, ctx) {
  var pot = ctx.pot || 0;
  if (!pot) return {};
  var humans = ctx.players.filter(function (p) { return p.kind === 'human' && p.active !== false; });
  if (!humans.length) return {};
  var recipients = humans;
  if (s.winner >= 0) {
    var w = ctx.players[s.winner];
    if (w && w.kind === 'human' && w.active !== false) recipients = [w];
  }
  var out = {}, share = Math.floor(pot / recipients.length), rest = pot - share * recipients.length;
  recipients.forEach(function (p, i) { out[p.id] = share + (i < rest ? 1 : 0); });
  return out;
}
function owFresh() {
  return {pits: [4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4], stores: [0, 0], turn: 0, winner: -1, turns: 0, over: false, last_move: null};
}
const game = {
  newMatch(ctx) { return {state: owFresh(), turn: [ctx.players[0].id]}; },
  applyMove(state, id, move, ctx) {
    if (!state || state.over || !move || typeof move !== 'object' || Array.isArray(move)) throw new InvalidMove('Illegal move');
    var seat = -1;
    for (var i = 0; i < ctx.players.length; i++) if (ctx.players[i].id === id) seat = i;
    if (seat !== state.turn) throw new InvalidMove('Illegal move');
    var options = owLegal(state), keys = Object.keys(move);
    var ok = options.some(function (m) {
      return Object.keys(m).length === keys.length &&
        keys.every(function (k) { return Object.prototype.hasOwnProperty.call(m, k) && m[k] === move[k]; });
    });
    if (!ok) throw new InvalidMove('Illegal move');
    var s = owCopy(state);
    s.turns++;
    var rec = {};
    owSow(s, seat, move.pit, rec);
    // There is no game-end sweep in these rules: seeds left on the board
    // at the end are awarded to nobody, so this sow record stays the
    // complete last move even when the move ends the game.
    s.last_move = {kind: 'sow', seat: seat, from_pit: move.pit,
      seeds: state.pits[move.pit], landings: rec.landings,
      last_pit: rec.landings[rec.landings.length - 1],
      captures: rec.captures, captured: rec.captured};
    // Endings, checked after every move: a store over 24 wins at once;
    // at most 6 seeds left on the board ends the game; and if the player
    // to move has no legal move -- above all because they cannot feed the
    // mover's now-empty side -- the game ends too. Board seeds left over
    // are awarded to nobody; the stores alone decide.
    if (s.stores[0] > 24 || s.stores[1] > 24 || owBoardTotal(s) <= 6 || owLegalFor(s, 1 - seat).length === 0) {
      owFinish(s);
    } else {
      s.turn = 1 - seat;
    }
    return s.over ? {state: s, turn: null, payouts: owPayouts(s, ctx)} : {state: s, turn: [ctx.players[s.turn].id]};
  },
  viewFor(state, id, ctx) {
    var s = owCopy(state);
    if (s.last_move === undefined) s.last_move = null;
    s.legal = (!state.over && ctx.players[state.turn] && ctx.players[state.turn].id === id) ? owLegal(state) : [];
    return s;
  },
  randomMove(s, id, ctx) {
    var options = owLegal(s);
    return options[Math.floor(ctx.random() * options.length)];
  },
  computerMove(s, id, ctx) {
    // Prefer the biggest capture, then the move that sows the most seeds
    // into the opponent side (which also feeds when feeding is required);
    // ties go to the lowest pit, so the choice is deterministic.
    var options = owLegal(s), best = null, bestScore = -1;
    for (var i = 0; i < options.length; i++) {
      var trial = {pits: s.pits.slice(), stores: s.stores.slice()};
      var captured = owSow(trial, s.turn, options[i].pit);
      var score = captured * 100 + owSownIntoOpp(s.pits, s.turn, options[i].pit);
      if (score > bestScore) { bestScore = score; best = options[i]; }
    }
    return best;
  }
};

declarative_ui.ui_code:
const SOURCE_STRINGS={"title": "Oware", "turn": "Player {n} to move", "finished": "Finished", "sow": "Sow pit {n}", "score": "Captured {a} : {b}", "store": "Player {n} store", "server_invalid": "Illegal move"};
// Oware presentation: a graph board whose 12 cells are the pits in ring
// order (seat 0 along the bottom left to right, seat 1 back along the top),
// plus a tray board holding the two captured-seed stores. Only the acting
// viewer receives targets; spectators and the waiting player receive none.
const gameUI = {
  reduce(message, localState) {
    const m = message.type === 'ui_event' ? message.state_changed : message;
    const s = m.view || m.state;
    const strings = Object.assign({}, SOURCE_STRINGS, m.strings || {});
    const t = (key, args = {}) => (strings[key] || key).replace(/\{(\w+)\}/g, (_, k) => String(args[k] === undefined ? '' : args[k]));
    const active = m.status === 'ongoing' && !m.replay && m.acting_for_player_index !== null && m.acting_for_player_index !== undefined;
    const legal = active ? (s.legal || []) : [];
    const pieces = [], targets = [], controls = [];
    const labels = [
      {id: 'title', text: t('title'), x: 24, y: 18, font_size: 26},
      {id: 'turn', text: m.status === 'over' || s.over ? t('finished') : t('turn', {n: s.turn + 1}), x: 24, y: 54, font_size: 18},
      {id: 'score', text: t('score', {a: s.stores[0], b: s.stores[1]}), x: 380, y: 54, font_size: 18},
      {id: 'store_label_0', text: t('store', {n: 1}), x: 84, y: 344, font_size: 14},
      {id: 'store_label_1', text: t('store', {n: 2}), x: 384, y: 344, font_size: 14}
    ];
    const keyOf = move => Object.keys(move).map(k => k + '_' + move[k]).join('_');
    s.pits.forEach((n, pit) => pieces.push({
      id: 'pit_' + pit, type: pit < 6 ? 'p0' : 'p1', board: 'main',
      position: {cell: String(pit)}, text: String(n),
      actions: []
    }));
    pieces.push({id: 'store_0', type: 'store', board: 'tray', position: {x: 60, y: 26}, text: String(s.stores[0]), actions: []});
    pieces.push({id: 'store_1', type: 'store', board: 'tray', position: {x: 360, y: 26}, text: String(s.stores[1]), actions: []});
    legal.forEach(move => targets.push({id: keyOf(move), board: 'main', position: {cell: String(move.pit)}, label: t('sow', {n: move.pit + 1})}));
    const scene = {pieces, targets, controls, labels};
    const out = {scene, local_state: {}};
    if (message.type === 'ui_event' && active && message.event.type === 'tap') {
      let id = message.event.id;
      if (id && id.startsWith('pit_')) id = 'type_sow_pit_' + id.slice(4);
      const move = legal.find(option => keyOf(option) === id);
      if (move) out.make_move = move;
    }
    return out;
  },
  // Count-based rendering: each pit is a single piece (pit_<index>) whose
  // text is the seed COUNT in that pit, and each store is a single piece
  // whose text is its captured count. There are no individual seed pieces
  // with stable IDs, so a sow has no piece that could travel pit to pit
  // and captured seeds have no piece that could travel to a store.
  // Explicitly return [] (no positional motion) rather than inventing a
  // fake hand piece; the server's view.last_move record still carries the
  // full ordered sow/capture detail for any future seed-piece rendering.
  getLastMoveAnimations(view, scene) {
    if (!Object.prototype.hasOwnProperty.call(view, 'last_move')) return null;
    return [];
  }
};
